def test_export_bundle_complete() -> None:
    parts = report_bundle_parts()
    assert parts["report"].endswith(".html")
    assert parts["script"] == "reproduce.py"
    assert parts["manifest"] == "manifest.json"


def test_export_native_and_onnx() -> None:
    plan = export_plan(onnx_available=False)
    assert plan["native"] == "joblib"
    assert plan["onnx"] is None
    mobile = export_plan(onnx_available=True)
    assert mobile["onnx"] == "onnx"
